mapper.select:
UPDATE user_character_info
SET favor_value = LEAST(100, GREATEST(0, COALESCE(favor_value, 0) + #{favorChange}))
WHERE user_world_id = #{userWorldId}
  AND character_id = #{characterId}
RETURNING favor_value

UPDATE user_character_info
SET user_info_prompt = CASE
    WHEN NULLIF(BTRIM(user_info_prompt), '') IS NULL THEN #{userInfoPrompt}
    ELSE user_info_prompt || E'\n' || #{userInfoPrompt}
END
WHERE user_world_id = #{userWorldId}
  AND character_id = #{characterId}
RETURNING user_info_prompt

SELECT COUNT(1)
FROM user_character_info
WHERE user_world_id = #{userWorldId}
